import sys

def solve(n, arr):
    trie = {}
    def insert(num):
        node = trie
        for i in range(29, -1, -1):
            bit = (num >> i) & 1
            if bit not in node: node[bit] = {}
            node = node[bit]
    def query(num):
        node = trie; val = 0
        for i in range(29, -1, -1):
            bit = (num >> i) & 1; want = 1 - bit
            if want in node: val |= (1 << i); node = node[want]
            else: node = node.get(bit, {})
        return val
    for num in arr: insert(num)
    return str(max(query(num) for num in arr))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))
    print(solve(n, arr))

